package com.example.appanh;

import android.content.*;
import android.net.Uri;
import android.os.Bundle;
import android.text.*;
import android.view.*;
import android.widget.*;
import androidx.activity.result.*;
import androidx.activity.result.contract.ActivityResultContracts;
import androidx.recyclerview.widget.*;
import com.example.appanh.models.*;
import com.google.android.material.appbar.MaterialToolbar;
import com.google.android.material.bottomsheet.BottomSheetDialog;
import java.util.*;

/** Gallery behavior is Java; screen structure is defined in res/layout. */
public class GalleryActivity extends BaseActivity {
 protected final Set<String> selected=new LinkedHashSet<>();
 protected String type="all",query="",sort="newest",albumId;
 protected boolean importing,selecting,showHidden;
 private ImportViewModel importModel;
 private final ActivityResultLauncher<String[]> picker=registerForActivityResult(new ActivityResultContracts.OpenMultipleDocuments(),uris->{if(!uris.isEmpty())importFiles(uris);});
 @Override public void onCreate(Bundle state){super.onCreate(state);albumId=getIntent().getStringExtra("albumId");
  int layout=this instanceof AlbumActivity?R.layout.activity_album:this instanceof CreateAlbumActivity?R.layout.activity_create_album:this instanceof AlbumDetailActivity?R.layout.activity_album_detail:this instanceof TrashActivity?R.layout.activity_trash:this instanceof SearchActivity?R.layout.activity_search:R.layout.activity_main;
  screen(layout);MaterialToolbar toolbar=findViewById(R.id.toolbar);
  if(this instanceof MainActivity||this instanceof SearchActivity||this instanceof HiddenMediaActivity){toolbar.inflateMenu(R.menu.gallery_actions);for(int i=0;i<toolbar.getMenu().size();i++){android.graphics.drawable.Drawable icon=toolbar.getMenu().getItem(i).getIcon();if(icon!=null)icon.mutate().setTint(androidx.core.content.ContextCompat.getColor(this,R.color.text_primary));}toolbar.setOnMenuItemClickListener(item->{if(item.getItemId()==R.id.galleryFilter)filter();else options();return true;});}
  if(this instanceof AlbumDetailActivity){toolbar.inflateMenu(R.menu.album_actions);for(int i=0;i<toolbar.getMenu().size();i++){android.graphics.drawable.Drawable icon=toolbar.getMenu().getItem(i).getIcon();if(icon!=null)icon.mutate().setTint(getColor(R.color.text_primary));}toolbar.setOnMenuItemClickListener(item->{if(item.getItemId()==R.id.addPhotos)addPhotos();else albumOptions();return true;});selecting=getIntent().getBooleanExtra("selecting",false);}
  EditText search=findViewById(R.id.search);if(search!=null){search.addTextChangedListener(new TextWatcher(){public void beforeTextChanged(CharSequence s,int a,int c,int f){}public void onTextChanged(CharSequence s,int a,int b,int c){query=s.toString().toLowerCase(Locale.ROOT);render();}public void afterTextChanged(Editable e){}});search.setOnEditorActionListener((view,action,event)->{if(action!=android.view.inputmethod.EditorInfo.IME_ACTION_SEARCH)return false;((android.view.inputmethod.InputMethodManager)getSystemService(INPUT_METHOD_SERVICE)).hideSoftInputFromWindow(view.getWindowToken(),0);view.clearFocus();return true;});}
  click(R.id.all,()->{type="all";render();});click(R.id.images,()->{type="images";render();});click(R.id.videos,()->{type="videos";render();});click(R.id.favorites,()->{type="favorites";render();});
  com.google.android.material.floatingactionbutton.FloatingActionButton importButton=findViewById(R.id.importMedia);if(importButton!=null){importButton.setImageDrawable(androidx.appcompat.content.res.AppCompatResources.getDrawable(this,R.drawable.ic_add).mutate());importButton.setImageTintList(android.content.res.ColorStateList.valueOf(getColor(R.color.white)));}
  click(R.id.importMedia,()->picker.launch(new String[]{"image/*","video/*"}));click(R.id.sort,this::filter);
  click(R.id.createAlbum,()->go(CreateAlbumActivity.class));click(R.id.create,this::createAlbum);
  click(R.id.addPhotos,this::addPhotos);click(R.id.albumOptions,this::albumOptions);click(R.id.emptyTrash,this::emptyTrash);
  getOnBackPressedDispatcher().addCallback(this,new androidx.activity.OnBackPressedCallback(true){public void handleOnBackPressed(){if(selecting){selecting=false;selected.clear();render();}else{setEnabled(false);getOnBackPressedDispatcher().onBackPressed();setEnabled(true);}}});
  importModel=new androidx.lifecycle.ViewModelProvider(this).get(ImportViewModel.class);
  importModel.progress.observe(this,value->{importing=importModel.busy;if(importButton!=null)importButton.setEnabled(!importing);if(importing)status(value);});
  importModel.completed.observe(this,message->{if(message==null)return;importModel.completed.setValue(null);importing=false;reload();toast(message);});
  if(state!=null){selected.addAll(state.getStringArrayList("selected")==null?Collections.emptyList():state.getStringArrayList("selected"));sort=state.getString("sort","newest");type=state.getString("type","all");query=state.getString("query","");showHidden=state.getBoolean("showHidden");selecting=state.getBoolean("selecting");if(search!=null)search.setText(query);int chip=type.equals("images")?R.id.images:type.equals("videos")?R.id.videos:type.equals("favorites")?R.id.favorites:R.id.all;android.widget.CompoundButton selectedChip=findViewById(chip);if(selectedChip!=null)selectedChip.setChecked(true);}
 }
 @Override protected void onResume(){super.onResume();if(!importing)reload();}
 @Override protected void onSaveInstanceState(Bundle out){out.putStringArrayList("selected",new ArrayList<>(selected));out.putString("sort",sort);out.putString("type",type);out.putString("query",query);out.putBoolean("showHidden",showHidden);out.putBoolean("selecting",selecting);super.onSaveInstanceState(out);}
 protected void reload(){repo.load((p,a,error)->{if(isFinishing()||isDestroyed())return;render();if(error!=null)status(error);else if(this instanceof TrashActivity){List<Photo> expired=new ArrayList<>();long cutoff=System.currentTimeMillis()-30L*24*60*60*1000;for(Photo photo:p)if(photo.isDeleted()&&photo.getDeletedAt()!=null&&photo.getDeletedAt().getTime()<cutoff)expired.add(photo);if(!expired.isEmpty())removeNext(expired,0);}else if(this instanceof MainActivity&&getSharedPreferences("backup-"+repo.uid(),0).getBoolean("auto",false))BackupActivity.backup(this,repo,false,()->{});},()->{if(!isFinishing()&&!isDestroyed())render();});}
 protected List<Photo> visible(){return GalleryQuery.apply(repo.photos,this instanceof TrashActivity,showHidden,this instanceof AlbumDetailActivity?albumId:null,type,query,sort);}
 private Intent detailIntent(Photo photo){return new Intent(this,PhotoDetailActivity.class).putExtra("photoId",photo.getId()).putExtra("albumId",this instanceof AlbumDetailActivity?albumId:null).putExtra("type",type).putExtra("query",query).putExtra("sort",sort);}
 protected void render(){
  if(isFinishing()||isDestroyed())return;
  RecyclerView grid=findViewById(R.id.grid);if(grid==null)return;boolean albumScreen=this instanceof AlbumActivity;
  if(grid.getLayoutManager()==null){int columns=this instanceof TrashActivity?1:Math.max(albumScreen?2:3,(int)(getResources().getConfiguration().screenWidthDp/(albumScreen?180f:120f)));grid.setLayoutManager(new GridLayoutManager(this,columns));grid.setItemAnimator(null);}List<Album> orderedAlbums=new ArrayList<>(repo.albums);orderedAlbums.sort(Comparator.comparingLong((Album album)->album.getCreatedAt()==null?0:album.getCreatedAt().getTime()).reversed());List<?> items=albumScreen?orderedAlbums:visible();View empty=findViewById(R.id.emptyState);if(empty!=null){empty.setVisibility(items.isEmpty()?View.VISIBLE:View.GONE);if(empty instanceof android.view.ViewGroup){android.view.ViewGroup group=(android.view.ViewGroup)empty;if(group.getChildCount()>=3&&group.getChildAt(1) instanceof TextView&&group.getChildAt(2) instanceof TextView){boolean filtered=!query.trim().isEmpty()||!type.equals("all");((TextView)group.getChildAt(1)).setText(filtered?"Không tìm thấy kết quả":showHidden?"Chưa có ảnh hoặc video đã ẩn":"Lưu giữ những điều bạn yêu");((TextView)group.getChildAt(2)).setText(filtered?"Thử tên khác hoặc chọn Tất cả để xem thêm ảnh và video.":showHidden?"Nhấn giữ một mục trong thư viện rồi chọn Ẩn. Nhấn giữ mục tại đây để bỏ ẩn.":"Thêm ảnh hoặc video đầu tiên để bắt đầu câu chuyện của bạn.");}}}
  if(grid.getAdapter() instanceof MediaAdapter)((MediaAdapter)grid.getAdapter()).update(items);else grid.setAdapter(new MediaAdapter(items,repo,selected,new MediaAdapter.Events(){public void tap(Object item){if(item instanceof Album){startActivity(new Intent(GalleryActivity.this,AlbumDetailActivity.class).putExtra("albumId",((Album)item).getId()));return;}Photo p=(Photo)item;if(GalleryActivity.this instanceof CreateAlbumActivity||selecting){if(!selected.add(p.getId()))selected.remove(p.getId());render();}else if(GalleryActivity.this instanceof TrashActivity)trashActions(p);else startActivity(detailIntent(p));}public void hold(Object item){if(item instanceof Photo)photoMenu((Photo)item);else{albumId=((Album)item).getId();albumOptions();}}},this instanceof TrashActivity));
  status(items.isEmpty()?(empty!=null?"":albumScreen?"Chưa có album. Nhấn Tạo album để bắt đầu.":this instanceof TrashActivity?"Thùng rác đang trống.":"Thêm ảnh từ tab Ảnh để bắt đầu."):(showHidden?"Đã ẩn • ":"")+items.size()+" "+(albumScreen?"album":"mục")+(selected.isEmpty()?"":" • Đã chọn "+selected.size()));
  View emptyTrashButton=findViewById(R.id.emptyTrash);if(emptyTrashButton!=null)emptyTrashButton.setEnabled(!items.isEmpty());
  if(importing)status("Đang nhập ảnh và video…");
  if(this instanceof AlbumDetailActivity){Album album=repo.album(albumId);if(album!=null)((MaterialToolbar)findViewById(R.id.toolbar)).setTitle(album.getName());}
 }
 private void filter(){BottomSheetDialog dialog=sheet(R.layout.sheet_filter);for(int id:new int[]{R.id.newest,R.id.oldest,R.id.size,R.id.type})dialog.findViewById(id).setOnClickListener(v->{sort=id==R.id.newest?"newest":id==R.id.oldest?"oldest":id==R.id.size?"size":"type";dialog.dismiss();render();});dialog.show();}
 private BottomSheetDialog sheet(int layout){BottomSheetDialog d=new BottomSheetDialog(this);d.setContentView(layout);d.setOnShowListener(dialog -> d.getBehavior().setState(com.google.android.material.bottomsheet.BottomSheetBehavior.STATE_EXPANDED));MaterialToolbar bar=d.findViewById(R.id.toolbar);if(bar!=null)bar.setNavigationOnClickListener(v->d.dismiss());return d;}
 private android.app.Dialog optionsPopup(){android.app.Dialog dialog=new android.app.Dialog(this);dialog.setContentView(R.layout.sheet_options);android.view.Window window=dialog.getWindow();if(window!=null){window.setBackgroundDrawableResource(android.R.color.transparent);window.setGravity(android.view.Gravity.TOP|android.view.Gravity.END);window.setLayout((int)(264*getResources().getDisplayMetrics().density),android.view.WindowManager.LayoutParams.WRAP_CONTENT);android.view.WindowManager.LayoutParams params=window.getAttributes();params.y=(int)(64*getResources().getDisplayMetrics().density);params.x=(int)(12*getResources().getDisplayMetrics().density);params.dimAmount=.28f;window.setAttributes(params);}com.google.android.material.appbar.MaterialToolbar bar=dialog.findViewById(R.id.toolbar);if(bar!=null)bar.setVisibility(View.GONE);return dialog;}
 private void options(){android.app.Dialog d=optionsPopup();((TextView)d.findViewById(R.id.select)).setText(selecting?"Thoát chọn nhiều":"Chọn nhiều");d.findViewById(R.id.addAlbum).setEnabled(!selected.isEmpty());com.google.android.material.button.MaterialButton hide=d.findViewById(R.id.hide);hide.setText(showHidden?"Bỏ ẩn các mục đã chọn":"Ẩn các mục đã chọn");hide.setEnabled(!selected.isEmpty());d.findViewById(R.id.hiddenMedia).setVisibility(showHidden?View.GONE:View.VISIBLE);d.findViewById(R.id.hiddenMedia).setOnClickListener(v->{d.dismiss();go(HiddenMediaActivity.class);});d.findViewById(R.id.select).setOnClickListener(v->{selecting=!selecting;selected.clear();render();status(selecting?"Chạm vào từng ảnh để chọn, sau đó mở menu → Thêm vào album":"Đã thoát chọn nhiều");d.dismiss();});d.findViewById(R.id.addAlbum).setOnClickListener(v->{d.dismiss();chooseAlbum(new ArrayList<>(selected));});d.findViewById(R.id.hide).setOnClickListener(v->{List<String> ids=new ArrayList<>(selected);repo.setHidden(ids,!showHidden,error->{result(error);selected.clear();selecting=false;render();});d.dismiss();});d.findViewById(R.id.settings).setOnClickListener(v->{go(SettingsActivity.class);d.dismiss();});d.findViewById(R.id.help).setOnClickListener(v->{toast("Thêm ảnh bằng nút +. Nhấn giữ ảnh để mở menu. Nhấn ảnh để xem và chỉnh sửa.");d.dismiss();});d.show();}
 private void photoMenu(Photo p){if(this instanceof TrashActivity){trashActions(p);return;}BottomSheetDialog d=sheet(R.layout.sheet_photo_context);((com.google.android.material.button.MaterialButton)d.findViewById(R.id.hide)).setText(p.isHidden()?"Bỏ ẩn":"Ẩn ảnh/video");d.findViewById(R.id.edit).setVisibility(p.isVideo()?View.GONE:View.VISIBLE);((TextView)d.findViewById(R.id.favorite)).setText(p.isFavorite()?"Bỏ yêu thích":"Yêu thích");int[] ids={R.id.info,R.id.addAlbum,R.id.favorite,R.id.hide,R.id.edit,R.id.share,R.id.trash};for(int id:ids)d.findViewById(id).setOnClickListener(v->{d.dismiss();if(id==R.id.info)PhotoDetailActivity.info(this,repo,p);else if(id==R.id.addAlbum)chooseAlbum(Collections.singletonList(p.getId()));else if(id==R.id.favorite){p.setFavorite(!p.isFavorite());repo.save(p,error->{result(error);render();});}else if(id==R.id.hide){repo.setHidden(Collections.singletonList(p.getId()),!p.isHidden(),error->{result(error);render();});}else if(id==R.id.edit)startActivity(new Intent(this,EditPhotoActivity.class).putExtra("photoId",p.getId()));else if(id==R.id.share)startActivity(new Intent(this,ShareActivity.class).putExtra("photoId",p.getId()));else confirm("Chuyển ảnh vào thùng rác?",()->{p.setDeleted(true);p.setDeletedAt(new Date());repo.save(p,error->{result(error);render();});});});d.show();}
 private void chooseAlbum(List<String> ids){if(ids.isEmpty()){toast("Nhấn Chọn nhiều và chọn ảnh trước.");return;}if(repo.albums.isEmpty()){toast("Bạn cần tạo album trước.");return;}String[] names=new String[repo.albums.size()];for(int i=0;i<names.length;i++)names[i]=repo.albums.get(i).getName();new androidx.appcompat.app.AlertDialog.Builder(this).setTitle("Thêm vào album").setItems(names,(d,index)->{String target=repo.albums.get(index).getId();saveMembership(ids,target,0,()->{selected.clear();selecting=false;render();});}).show();}
 private void createAlbum(){String name=input(R.id.albumName);if(name.isEmpty()||name.length()>80){toast("Tên album cần từ 1 đến 80 ký tự.");return;}findViewById(R.id.create).setEnabled(false);Album a=new Album(repo.uid(),name,"");a.setCreatedAt(new Date());repo.saveAlbum(a,error->{if(error!=null){result(error);findViewById(R.id.create).setEnabled(true);return;}saveMembership(new ArrayList<>(selected),a.getId(),0,()->{NotificationsActivity.record(this,"Đã tạo album "+name);finish();});});}
 private void saveMembership(List<String> ids,String target,int index,Runnable done){if(index>=ids.size()){done.run();return;}Photo p=repo.find(ids.get(index));if(p==null){saveMembership(ids,target,index+1,done);return;}if(!p.getAlbumIds().contains(target))p.getAlbumIds().add(target);repo.save(p,error->{if(error!=null){result(error);View create=findViewById(R.id.create);if(create!=null)create.setEnabled(true);return;}saveMembership(ids,target,index+1,done);});}
 private void addPhotos(){List<Photo> candidates=new ArrayList<>();for(Photo p:repo.photos)if(!p.isDeleted()&&!p.isHidden()&&!p.getAlbumIds().contains(albumId))candidates.add(p);if(candidates.isEmpty()){toast("Không còn ảnh để thêm. Hãy nhập ảnh ở tab Ảnh.");return;}String[] labels=new String[candidates.size()];boolean[] checked=new boolean[candidates.size()];for(int i=0;i<labels.length;i++)labels[i]=candidates.get(i).getFileName();new androidx.appcompat.app.AlertDialog.Builder(this).setTitle("Chọn ảnh").setMultiChoiceItems(labels,checked,(d,i,c)->checked[i]=c).setNegativeButton("Hủy",null).setPositiveButton("Thêm",(d,w)->{List<String> ids=new ArrayList<>();for(int i=0;i<checked.length;i++)if(checked[i])ids.add(candidates.get(i).getId());saveMembership(ids,albumId,0,this::render);}).show();}
 private void albumOptions(){
  Album album=repo.album(albumId);if(album==null)return;
  BottomSheetDialog dialog=sheet(R.layout.sheet_album_options);
  dialog.findViewById(R.id.removeSelected).setVisibility(this instanceof AlbumDetailActivity&&!selected.isEmpty()?View.VISIBLE:View.GONE);
  dialog.findViewById(R.id.select).setOnClickListener(view->{dialog.dismiss();if(this instanceof AlbumDetailActivity){selecting=!selecting;selected.clear();render();if(selecting)status("Chạm để chọn ảnh → menu → Bỏ ảnh đã chọn khỏi album");}else startActivity(new Intent(this,AlbumDetailActivity.class).putExtra("albumId",albumId).putExtra("selecting",true));});
  dialog.findViewById(R.id.addPhotos).setOnClickListener(view->{dialog.dismiss();addPhotos();});
  dialog.findViewById(R.id.renameAlbum).setOnClickListener(view->{dialog.dismiss();ask("Tên album",album.getName(),name->{album.setName(name);repo.saveAlbum(album,error->{result(error);render();});});});
  dialog.findViewById(R.id.removeSelected).setOnClickListener(view->{dialog.dismiss();removeMembership(new ArrayList<>(selected),0);});
  dialog.findViewById(R.id.deleteAlbum).setOnClickListener(view->{dialog.dismiss();confirm("Xóa album? Ảnh vẫn được giữ trong thư viện.",()->repo.deleteAlbum(album,error->{if(error!=null){result(error);return;}if(this instanceof AlbumDetailActivity)finish();else render();}));});
  dialog.show();
 }
 private void removeMembership(List<String> ids,int index){if(index>=ids.size()){selected.clear();selecting=false;render();return;}Photo photo=repo.find(ids.get(index));if(photo==null){removeMembership(ids,index+1);return;}photo.getAlbumIds().remove(albumId);repo.save(photo,error->{if(error!=null){result(error);return;}removeMembership(ids,index+1);});}
 private void trashActions(Photo p){new androidx.appcompat.app.AlertDialog.Builder(this).setTitle(p.getFileName()).setItems(new String[]{"Khôi phục","Xóa vĩnh viễn"},(d,i)->{if(i==0){p.setDeleted(false);p.setDeletedAt(null);repo.save(p,error->{result(error);render();});}else confirm("Xóa vĩnh viễn ảnh này?",()->repo.remove(p,error->{result(error);render();}));}).show();}
 private void emptyTrash(){List<Photo> trash=visible();if(trash.isEmpty())return;confirm("Xóa vĩnh viễn "+trash.size()+" mục?",()->removeNext(trash,0));}
 private void removeNext(List<Photo> list,int i){if(i>=list.size()){render();return;}repo.remove(list.get(i),error->{if(error!=null){result(error);render();return;}removeNext(list,i+1);});}
 private void importFiles(List<Uri> uris){importModel.start(uris);}
}
